const sumMonthlyCoachingSpend = `-- name: SumMonthlyCoachingSpend :one
SELECT COALESCE(sum(x.amount),0)::bigint FROM (
 SELECT amount_yen::bigint AS amount FROM review_payments WHERE payer_id = $1::uuid
 AND request_id IS DISTINCT FROM $2::uuid
 AND created_at >= date_trunc('month',now() AT TIME ZONE 'Asia/Tokyo') AT TIME ZONE 'Asia/Tokyo'
 AND (status IN ('authorized','captured') OR (status='pending' AND session_expires_at>now()))
 UNION ALL
 SELECT (pay.amount_yen-pay.refunded_yen)::bigint FROM coaching_payments pay JOIN coaching_contracts ct ON ct.id=pay.contract_id
 WHERE ct.requester_id = $1::uuid AND ct.id IS DISTINCT FROM $3::uuid
 AND pay.created_at >= date_trunc('month',now() AT TIME ZONE 'Asia/Tokyo') AT TIME ZONE 'Asia/Tokyo'
 AND (pay.status IN ('paid','partially_refunded') OR (pay.status='pending' AND pay.session_expires_at>now()))
 UNION ALL
 SELECT (amount_yen-refunded_yen)::bigint FROM coaching_ticket_purchases WHERE owner_id = $1::uuid
 AND id IS DISTINCT FROM $4::uuid
 AND COALESCE(paid_at,created_at) >= date_trunc('month',now() AT TIME ZONE 'Asia/Tokyo') AT TIME ZONE 'Asia/Tokyo'
 AND (status IN ('paid','partially_refunded') OR (status='pending' AND session_expires_at>now()))
 UNION ALL
 SELECT c.price_yen::bigint FROM coaching_consultations c WHERE c.requester_id=$1::uuid
 AND c.funding='cash' AND c.id IS DISTINCT FROM $5::uuid
 AND COALESCE(c.paid_at,c.updated_at)>=date_trunc('month',now() AT TIME ZONE 'Asia/Tokyo') AT TIME ZONE 'Asia/Tokyo'
 AND (c.payment_state IN ('paid','refund_pending') OR (c.status='awaiting_payment' AND c.expires_at>now() AND (c.session_expires_at IS NULL OR c.session_expires_at>now())))
) x
`

type SumMonthlyCoachingSpendParams struct {
	OwnerID               uuid.UUID `json:"owner_id"`
	ExcludeReviewID       uuid.UUID `json:"exclude_review_id"`
	ExcludeContractID     uuid.UUID `json:"exclude_contract_id"`
	ExcludePurchaseID     uuid.UUID `json:"exclude_purchase_id"`
	ExcludeConsultationID uuid.UUID `json:"exclude_consultation_id"`
}

func (q *Queries) SumMonthlyCoachingSpend(ctx context.Context, arg SumMonthlyCoachingSpendParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumMonthlyCoachingSpend,
		arg.OwnerID,
		arg.ExcludeReviewID,
		arg.ExcludeContractID,
		arg.ExcludePurchaseID,
		arg.ExcludeConsultationID,
	)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

